/* Dev project browser */
.project-browser {
  width: min(100%, 52rem);
  min-height: 22rem;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  position: relative;
  border: 1px solid color-mix(in srgb, var(--ink) 18%, transparent);
  background: color-mix(in srgb, var(--cream) 70%, transparent);
}

.project-browser:has(.project-browser__body--embed) {
  min-height: min(70vh, 40rem);
}

.project-browser__tabs-head {
  background: color-mix(in srgb, var(--ink) 88%, transparent);
  min-height: 2.5rem;
  display: flex;
  align-items: stretch;
  padding: 0 0.5rem;
}

.project-browser__tabs {
  display: flex;
  align-items: stretch;
  gap: 0;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.project-browser__tabs::-webkit-scrollbar {
  display: none;
}

.project-browser__tab {
  position: relative;
  flex: 0 0 auto;
  max-width: 9rem;
  min-height: 2.5rem;
  border: 0;
  border-right: 1px solid color-mix(in srgb, white 10%, transparent);
  border-radius: 0;
  background: transparent;
  color: color-mix(in srgb, white 55%, transparent);
  display: flex;
  gap: 0.4rem;
  align-items: center;
  padding: 0 0.85rem;
  cursor: pointer;
  font-family: inherit;
}

.project-browser__tab:hover {
  color: #fff;
  background: color-mix(in srgb, white 6%, transparent);
}

.project-browser__tab--open {
  color: #fff;
  background: color-mix(in srgb, white 10%, transparent);
  cursor: default;
}

.project-browser__tab--open:hover {
  background: color-mix(in srgb, white 10%, transparent);
}

.project-browser__tab--closable {
  padding-right: 0.45rem;
}

.project-browser__tab-label {
  font-size: 11px;
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
  text-align: left;
}

.project-browser__close-tab {
  color: inherit;
  font-size: 14px;
  line-height: 1;
  padding: 0.15rem 0.35rem;
  flex-shrink: 0;
  opacity: 0.55;
}

.project-browser__close-tab:hover {
  opacity: 1;
}

.project-browser__new-tab {
  flex: 0 0 auto;
  align-self: center;
  width: 1.75rem;
  height: 1.75rem;
  margin-left: 0.35rem;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: color-mix(in srgb, white 55%, transparent);
  font-family: inherit;
  font-size: 1.1rem;
  line-height: 1;
  display: grid;
  place-items: center;
  cursor: pointer;
}

.project-browser__new-tab:hover {
  color: #fff;
  background: color-mix(in srgb, white 8%, transparent);
}

.project-browser__head {
  z-index: 2;
  width: 100%;
  min-height: 2.25rem;
  background: color-mix(in srgb, var(--ink) 82%, transparent);
  padding: 0.45rem 0.85rem;
  display: flex;
  gap: 0.75rem;
  align-items: center;
  border-bottom: 1px solid color-mix(in srgb, var(--ink) 18%, transparent);
}

.project-browser__back {
  flex-shrink: 0;
  border: 0;
  background: transparent;
  color: color-mix(in srgb, white 70%, transparent);
  font-family: inherit;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 0;
  cursor: pointer;
}

.project-browser__back:hover {
  color: #fff;
}

.project-browser__address {
  margin: 0;
  flex: 1;
  min-width: 0;
  color: color-mix(in srgb, white 58%, transparent);
  font-size: 11px;
  letter-spacing: 0.06em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.project-browser__body {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 1.25rem;
  padding: 1.75rem 1.5rem 2rem;
  background: transparent;
  color: var(--ink);
  min-height: 16rem;
}

.project-browser__body--embed {
  position: relative;
  flex: 1;
  justify-content: stretch;
  gap: 0;
  padding: 0;
  min-height: min(58vh, 32rem);
  height: min(58vh, 32rem);
  background: color-mix(in srgb, white 35%, transparent);
  overflow: hidden;
}

.project-browser__frame-stage {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background: color-mix(in srgb, white 40%, transparent);
}

.project-browser__frame {
  display: block;
  border: 0;
  background: #fff;
  transform-origin: top left;
}

.project-browser__open-live {
  position: absolute;
  right: 12px;
  bottom: 12px;
  z-index: 2;
  pointer-events: auto;
  padding: 0.5rem 0.85rem;
  border: 1px solid color-mix(in srgb, var(--ink) 20%, transparent);
  border-radius: 0;
  background: color-mix(in srgb, var(--cream) 92%, transparent);
  color: var(--ink);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  text-decoration: none;
}

.project-browser__open-live:hover {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--cream);
}

.project-browser__meta {
  margin: 0;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.project-browser__title {
  margin: 0;
  font-family: var(--font-syne), sans-serif;
  font-size: clamp(2.5rem, 10vw, 5.5rem);
  line-height: 0.9;
  letter-spacing: 0.04em;
}

.project-browser__summary {
  margin: 0;
  max-width: 36rem;
  font-size: 14px;
  text-transform: uppercase;
  line-height: 1.5;
  letter-spacing: 0.06em;
}

.project-browser__link {
  align-self: flex-start;
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  text-decoration: underline;
  text-underline-offset: 4px;
  color: inherit;
}

.project-browser__see-it {
  align-self: flex-start;
  margin-top: 0.25rem;
  border: 1px solid var(--ink);
  background: var(--ink);
  color: var(--cream);
  padding: 0.7rem 1.25rem;
  font-family: inherit;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: background 160ms ease, color 160ms ease;
}

.project-browser__see-it:hover {
  background: transparent;
  color: var(--ink);
}

.project-browser__soon {
  margin: 0;
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--muted);
}

@media (max-width: 640px) {
  .project-browser__body:not(.project-browser__body--embed) {
    padding: 1.35rem 1.1rem 1.5rem;
    min-height: 14rem;
  }

  .project-browser:has(.project-browser__body--embed),
  .project-browser__body--embed {
    min-height: min(55vh, 28rem);
    height: min(55vh, 28rem);
  }
}

